# Guard every transition; completed transport alone is not success.
class GuardStop(Exception):
    pass

last_result = None
placed = False
reset_ok = False

def run_checked(name):
    global last_result
    r = robo.skill(name)
    print(name, r)
    last_result = r
    if not isinstance(r, dict):
        raise GuardStop('Unknown result format')
    # Verification never replays motion. Recovery is bounded and owner-authorized.
    for _ in range(2):
        if r.get('outcome') == 'pending_review' and r.get('verification_request_id'):
            r = robo.recheck(name, r['verification_request_id'])
        elif (r.get('outcome') == 'motion_stalled' and r.get('resume_request_id')
              and r.get('measured_stationary') is True):
            r = robo.resume(name, r['resume_request_id'])
        else:
            break
        print(name + ' recovery', r)
        last_result = r
        if not isinstance(r, dict):
            raise GuardStop('Unknown recovery format')
    if r.get('outcome') != 'success':
        raise GuardStop('Stopped at ' + name + ': ' + str(r.get('outcome')))
    return r

try:
    print('Prepared task:', robo.task)
    scene = robo.observe()
    print('Fresh scene:', scene)
    for name in ('approach_grasp', 'grasp', 'verify_grasp', 'inspect_in_hand',
                 'transfer_above_hole', 'align', 'insert', 'release', 'verify_placed'):
        run_checked(name)
        if name == 'verify_placed':
            placed = True
    run_checked('withdraw_reset')
    reset_ok = True
except GuardStop as e:
    print(str(e))
